package clusterdata.datatypes;

import java.io.Serializable;

public class TaskEvent implements Serializable {
    public long timestamp;
    public String missingInfo;
    public long jobId;
    public int taskIndex;
    public long machineId;
    public int eventType;
    public String userName;
    public int schedulingClass;
    public int priority;
    public double cpuCores;
    public double ram;
    public double disk;
    public boolean differentMachineConstraint;

    public TaskEvent() {}

    public static TaskEvent fromString(String line) {
        String[] tokens = line.split(",");
        if (tokens.length < 13) {
            return null;
        }

        TaskEvent event = new TaskEvent();
        event.timestamp = tokens[0].isEmpty() ? 0L : Long.parseLong(tokens[0]);
        event.missingInfo = tokens[1];
        event.jobId = tokens[2].isEmpty() ? 0L : Long.parseLong(tokens[2]);
        event.taskIndex = tokens[3].isEmpty() ? 0 : Integer.parseInt(tokens[3]);
        event.machineId = tokens[4].isEmpty() ? 0L : Long.parseLong(tokens[4]);
        event.eventType = tokens[5].isEmpty() ? 0 : Integer.parseInt(tokens[5]);
        event.userName = tokens[6];
        event.schedulingClass = tokens[7].isEmpty() ? 0 : Integer.parseInt(tokens[7]);
        event.priority = tokens[8].isEmpty() ? 0 : Integer.parseInt(tokens[8]);
        event.cpuCores = tokens[9].isEmpty() ? 0.0 : Double.parseDouble(tokens[9]);
        event.ram = tokens[10].isEmpty() ? 0.0 : Double.parseDouble(tokens[10]);
        event.disk = tokens[11].isEmpty() ? 0.0 : Double.parseDouble(tokens[11]);
        event.differentMachineConstraint = tokens.length > 12 && !tokens[12].isEmpty() && (tokens[12].equals("1") || tokens[12].equalsIgnoreCase("true"));

        return event;
    }

    public long getTimestamp() {
        return timestamp;
    }
}

